const removeToast = (id) => { toasts.value = toasts.value.filter(t => t.id !== id); };
const showPopup = (title, message, type = 'info', confirmText = 'Đã hiểu', onConfirm = null, showCancel = false) => { popup.value = { show: true, title, message, type, confirmText, showCancel, cancelText: 'Hủy', onConfirm }; };
