const toggleBookmark = (card) => { const idx = bookmarks.value.indexOf(card.id); if (idx >= 0) { bookmarks.value.splice(idx, 1); showToast(`Đã bỏ lưu: ${card.title}`, 'info'); } else { bookmarks.value.push(card.id); showToast(`Đã lưu bài: ${card.title}`, 'success'); } localStorage.setItem('tnhub_bookmarks', JSON.stringify(bookmarks.value)); };
