const submitNewPost = () => { const locName = getDistrictName(postForm.value.district); const newCard = { id: 'tn_' + Date.now(), badge: postForm.value.badge || 'Mới đăng', image: postForm.value.imageBase64 || postForm.value.previewUrl || 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=800&q=80', title: postForm.value.title, subtitle: (postForm.value.address ? postForm.value.address + ' - ' : '') + locName, price: postForm.value.price || 'Thỏa thuận', subprice: postForm.value.subprice || 'Vừa xong', category: postForm.value.category, btnType: postForm.value.category === 'tuyendung' ? 'apply' : (postForm.value.category === 'suachua' ? 'call' : 'contact'), location: locName, district: postForm.value.district, description: postForm.value.description, authorName: postForm.value.contactName || 'Phạm Thanh Quang', phone: postForm.value.contactPhone || '0908.123.456', authorEmail: 'ptquang0968@gmail.com', createdAt: new Date().toISOString() };
cards.value.unshift(newCard);
if (db) { try { addDoc(collection(db, 'listings'), newCard).catch(e => console.warn('Sync post to firestore notice:', e)); } catch (e) { console.warn('Firestore addDoc:', e); } }
showToast('Đăng tin thành công! Tin của bạn đã hiển thị ngay trên TN Hub.', 'success'); showPostModal.value = false;
postForm.value = { title: '', category: 'tuyendung', district: 'tptayninh', location: 'TP. Tây Ninh', address: '', price: '', subprice: '', badge: 'Tuyển gấp', description: '', contactName: 'Phạm Thanh Quang', contactPhone: '0908.123.456', imageBase64: null, previewUrl: '' }; };
const loginGoogle = async () => { try { if (!auth) throw new Error('Firebase Auth chưa khởi tạo'); const provider = new GoogleAuthProvider(); provider.setCustomParameters({ prompt: 'select_account' }); const res = await signInWithPopup(auth, provider); currentUser.value = res.user; showToast('Chào mừng ' + (res.user.displayName || '') + '!', 'success'); } catch (err) { console.warn('Login Auth info:', err.message); showToast('Đang ở phiên làm việc của ptquang0968@gmail.com', 'info'); } };
