// LẮNG NGHE REALTIME COLLECTION 'listings' TỪ FIREBASE if (db) { try { const listingsRef = collection(db, 'listings'); onSnapshot(listingsRef, (snapshot) => { if (!snapshot.empty) { const liveList = []; snapshot.forEach((d) => { liveList.push({ id: d.id, ...d.data() }); }); liveList.sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || '')); cards.value = liveList; isFirebaseConnected.value = true; console.log('Đã đồng bộ realtime từ Cloud Firestore'); } }, (err) => { console.warn('Firestore snapshot error:', err); }); } catch (err) { console.warn('Firestore setup error:', err); } } });
